program='''from collections import Counter, deque

def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            cells = []
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append((color, cells))
    return comps

def _shape(cells):
    mr=min(r for r,c in cells); mc=min(c for r,c in cells)
    return frozenset((r-mr,c-mc) for r,c in cells)

def transform(grid):
    out=[row[:] for row in grid]
    counts=Counter(v for row in grid for v in row)
    background=counts.most_common(1)[0][0]
    comps=[(color,cells) for color,cells in _components(grid) if color != background]
    # A small object inside another object's bounding box is the embedded sample.
    # Recolor a matching copy outside that box to the enclosing object's color.
    changes=[]
    for host_color, host in comps:
        hr0=min(r for r,c in host); hr1=max(r for r,c in host)
        hc0=min(c for r,c in host); hc1=max(c for r,c in host)
        for sample_color, sample in comps:
            if sample_color == host_color or len(sample)<2:
                continue
            sr0=min(r for r,c in sample); sr1=max(r for r,c in sample)
            sc0=min(c for r,c in sample); sc1=max(c for r,c in sample)
            if not (hr0 <= sr0 and sr1 <= hr1 and hc0 <= sc0 and sc1 <= hc1):
                continue
            # Exclude sample pixels that are actually part of the host (different colors normally guarantee this).
            shp=_shape(sample)
            for target_color,target in comps:
                if target_color != sample_color or target is sample or len(target)!=len(sample):
                    continue
                if _shape(target) != shp:
                    continue
                tr0=min(r for r,c in target); tr1=max(r for r,c in target)
                tc0=min(c for r,c in target); tc1=max(c for r,c in target)
                # The matching copy must lie outside the host's bounding box.
                if tr0 > hr1 or tr1 < hr0 or tc0 > hc1 or tc1 < hc0:
                    changes.append((target,host_color))
    for cells,color in changes:
        for r,c in cells: out[r][c]=color
    return out
'''
